/* Template:WorldEventTimetable/styles.css (set the content model to Sanitized CSS)
   The World Events timetable: daily events in seven day columns, game time events in their own panel.
   Dark colours are the default, the light theme overrides are at the bottom.
   Sanitized CSS has no CSS variables, so every colour is a literal value. */
.wev {
	margin: 0.8em 0 1.2em;
	color: #e8e1d6;
	font-size: 14px;
}
.wev-top {
	display: flex;
	flex-wrap: wrap;
	align-items: center;
	justify-content: space-between;
	gap: 10px 14px;
	margin-bottom: 14px;
}
.wev-tz, .wev-gclock {
	display: inline-flex;
	flex-wrap: wrap;
	align-items: center;
	gap: 8px;
	padding: 6px 12px;
	border: 1px solid #6a5340;
	border-radius: 18px;
	background: #241d18;
	font-size: 13px;
}
.wev-tz { margin-left: auto; }
.wev-gclock { display: none; }
.wev-js .wev-gclock:not(:empty) { display: inline-flex; }
.wev-tzlabel, .wev-gclabel { color: #9a9082; }
.wev-gcval { font-weight: 700; font-size: 15px; letter-spacing: .04em; color: #e8e1d6; }
.wev-tzname { font-weight: 700; color: #e8e1d6; }
.wev-tzsel {
	padding: 1px 4px;
	border: 1px solid #6a5340;
	border-radius: 6px;
	background: #1a1715;
	color: #e8e1d6;
	font-size: 12px;
}
.wev-note { margin-top: 10px; color: #9a9082; font-size: 12px; }
/* the seven days */
.wev-days {
	display: grid;
	grid-template-columns: repeat(7, minmax(0, 1fr));
	gap: 10px;
	align-items: start;
}
.wev-day { min-width: 0; }
.wev-dayhead {
	display: flex;
	align-items: center;
	justify-content: space-between;
	padding: 8px 10px;
	border: 1px solid #3a3430;
	border-radius: 8px;
	background: #241d18;
	font-size: 13px;
	font-weight: 700;
	letter-spacing: .1em;
	color: #c9bfb0;
}
.wev-today { display: none; font-size: 11px; letter-spacing: .06em; color: #e8e1d6; }
.wev-day-today .wev-today { display: inline; }
.wev-day-today .wev-dayhead { border-color: rgba(232, 225, 214, .5); background: rgba(232, 225, 214, .1); color: #ffffff; }
.wev-events { display: flex; flex-direction: column; gap: 8px; margin-top: 10px; }
/* one event: picture and time on the first line, the name under it */
.wev-ev {
	display: grid;
	grid-template-columns: 28px minmax(0, 1fr);
	grid-template-areas: "ico time" "text text";
	align-items: center;
	gap: 4px 8px;
	padding: 7px 8px;
	border: 1px solid #3a3430;
	border-radius: 8px;
	background: rgba(255, 255, 255, .035);
}
.wev-ev .wev-ico { grid-area: ico; }
.wev-ev .wev-time { grid-area: time; justify-self: end; }
.wev-ev .wev-text { grid-area: text; flex-direction: row; flex-wrap: wrap; align-items: baseline; justify-content: space-between; gap: 0 6px; }
.wev-ev .wev-name { flex: 1 1 auto; }
.wev-ev .wev-sub { flex: none; font-size: 11px; }
.wev-ev .wev-nexttag { flex: 0 0 100%; }
.wev-time, .wev-chip {
	padding: 2px 9px;
	border: 1px solid transparent;
	border-radius: 6px;
	font-size: 15px;
	font-weight: 700;
	letter-spacing: .03em;
	white-space: nowrap;
}
.wev-ico {
	position: relative;
	display: block;
	flex: none;
	width: 28px;
	height: 28px;
	overflow: hidden;
	border-radius: 6px;
	background: #26211d;
}
.wev-ico span, .wev-ico a { display: block; width: 100%; height: 100%; }
.wev-ico img { display: block; width: 100%; height: 100%; max-width: none; object-fit: cover; }
.wev-text { display: flex; flex-direction: column; gap: 1px; min-width: 0; }
.wev-name { font-size: 13px; font-weight: 600; line-height: 1.25; color: #e8e1d6; }
/* a name that links to its page keeps the white text */
.wev-name a, .wev-name a:visited, .wev-name a:hover, .wev-name a.new, .wev-name a.new:visited { color: inherit; }
.wev-name a:hover { text-decoration: underline; }
.wev-sub { font-size: 12px; color: #9a9082; }
.wev-nexttag { display: none; font-size: 11px; font-weight: 700; letter-spacing: .1em; color: #f5cb65; }
.wev-ev.wev-isnext { border-color: rgba(245, 203, 101, .7); background: rgba(245, 203, 101, .07); box-shadow: 0 0 14px rgba(245, 203, 101, .18); }
.wev-isnext .wev-nexttag { display: block; }
.wev-events:empty::after { content: "No events"; color: #6f6a5e; font-size: 12px; font-style: italic; text-align: center; }
/* the game time events */
.wev-gt { margin-top: 22px; }
.wev-gthead { display: flex; flex-wrap: wrap; align-items: baseline; gap: 4px 14px; margin-bottom: 10px; }
.wev-gttitle { font-size: 15px; font-weight: 700; letter-spacing: .06em; text-transform: uppercase; color: #f5cb65; }
.wev-gtnote { font-size: 12px; color: #9a9082; }
.wev-gcards { display: grid; grid-template-columns: repeat(auto-fill, minmax(250px, 1fr)); gap: 10px; }
.wev-gc { padding: 10px; border: 1px solid #3a3430; border-radius: 8px; background: rgba(255, 255, 255, .035); }
.wev-gctop { display: flex; align-items: center; gap: 10px; }
.wev-gctop .wev-ico { width: 36px; height: 36px; }
.wev-chips { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 10px; }
.wev-chip { padding: 1px 7px; font-size: 13px; font-weight: 600; letter-spacing: 0; }
.wev-chip-next { box-shadow: 0 0 0 1px rgba(245, 203, 101, .9); }
.wev-chipnone { font-size: 12px; color: #9a9082; }
/* the Gold Trader card: up for a while, gone for a while, on repeat */
.wev-tr { margin-top: 22px; padding: 10px 12px; border: 1px solid #3a3430; border-radius: 8px; background: rgba(255, 255, 255, .035); }
.wev-trtop { display: flex; flex-wrap: wrap; align-items: center; gap: 6px 10px; }
.wev-trtop .wev-ico { width: 36px; height: 36px; }
.wev-trstatus { margin-left: auto; font-size: 13px; font-weight: 700; color: #f5cb65; }
.wev-trstatus:empty { display: none; }
.wev-tr-active { border-color: rgba(123, 216, 143, .65); box-shadow: 0 0 14px rgba(123, 216, 143, .15); }
.wev-tr-active .wev-trstatus { color: #7bd88f; }
.wev-chip-active { box-shadow: 0 0 0 1px #7bd88f; }
/* chip colours */
.wev-c-mist .wev-time, .wev-c-mist .wev-chip { color: #ff9a6a; background: rgba(255, 138, 84, .15); border-color: rgba(255, 138, 84, .5); }
.wev-c-halcy .wev-time, .wev-c-halcy .wev-chip { color: #5fe0c8; background: rgba(60, 210, 185, .15); border-color: rgba(60, 210, 185, .5); }
.wev-c-luscas .wev-time, .wev-c-luscas .wev-chip { color: #c4a4ff; background: rgba(170, 130, 250, .15); border-color: rgba(170, 130, 250, .5); }
.wev-c-gold .wev-time, .wev-c-gold .wev-chip { color: #f5cb65; background: rgba(245, 203, 101, .15); border-color: rgba(245, 203, 101, .5); }
.wev-c-dgs .wev-time, .wev-c-dgs .wev-chip { color: #9fb4d6; background: rgba(140, 165, 205, .15); border-color: rgba(140, 165, 205, .5); }
.wev-c-veroe .wev-time, .wev-c-veroe .wev-chip { color: #8fd36b; background: rgba(120, 200, 80, .15); border-color: rgba(120, 200, 80, .5); }
.wev-c-abyss .wev-time, .wev-c-abyss .wev-chip { color: #6b9cff; background: rgba(90, 140, 255, .15); border-color: rgba(90, 140, 255, .5); }
.wev-c-sushi .wev-time, .wev-c-sushi .wev-chip { color: #ff8fb8; background: rgba(255, 120, 170, .15); border-color: rgba(255, 120, 170, .5); }
.wev-c-gr .wev-time, .wev-c-gr .wev-chip { color: #d68bff; background: rgba(200, 120, 255, .15); border-color: rgba(200, 120, 255, .5); }
.wev-c-jmg .wev-time, .wev-c-jmg .wev-chip { color: #ffb454; background: rgba(255, 156, 39, .15); border-color: rgba(255, 156, 39, .5); }
.wev-c-cr .wev-time, .wev-c-cr .wev-chip { color: #ff6a5a; background: rgba(240, 86, 60, .15); border-color: rgba(240, 86, 60, .5); }
.wev-c-sun .wev-time, .wev-c-sun .wev-chip { color: #ffe45c; background: rgba(255, 224, 80, .15); border-color: rgba(255, 224, 80, .5); }
.wev-c-hasla .wev-time, .wev-c-hasla .wev-chip { color: #a6dd4a; background: rgba(160, 215, 60, .15); border-color: rgba(160, 215, 60, .5); }
/* 12 hour clock (set by the script): the chips are wider */
.wev-12h .wev-time { padding: 2px 6px; font-size: 13px; letter-spacing: 0; }
.wev-12h .wev-chip { padding: 1px 5px; font-size: 12px; }
/* the day by day list, for phones (layout=agenda always, layout=auto on narrow screens). With scripts only today is open, a tap on a day opens it. */
.wev-agenda .wev-days { display: block; }
.wev-agenda .wev-day { margin-bottom: 14px; }
.wev-agenda .wev-dayhead { padding: 6px 4px; border: 0; border-bottom: 1px solid #3a3430; border-radius: 0; background: none; }
.wev-agenda .wev-day-today .wev-dayhead { border-bottom-color: rgba(232, 225, 214, .55); background: none; }
.wev-agenda .wev-events { margin-top: 8px; gap: 8px; }
.wev-agenda .wev-ev { grid-template-columns: 40px minmax(0, 1fr) auto; grid-template-areas: "ico text time"; align-items: center; gap: 12px; padding: 8px 12px 8px 8px; }
.wev-agenda .wev-ev .wev-ico { width: 40px; height: 40px; }
.wev-agenda .wev-ev .wev-text { margin: 0; flex-direction: column; flex-wrap: nowrap; align-items: stretch; gap: 1px; }
.wev-agenda .wev-ev .wev-sub { font-size: 12px; }
.wev-agenda .wev-events:empty { display: none; }
.wev-agenda .wev-dayhead { cursor: pointer; }
.wev-agenda .wev-dayhead::after { content: "\25BE"; margin-left: 8px; color: #9a9082; }
.wev-agenda .wev-day:not(.wev-open) .wev-dayhead::after { content: "\25B8"; }
.wev-js.wev-agenda .wev-day:not(.wev-open) .wev-events { display: none; }
@media (max-width: 1100px) {
.wev-auto .wev-days { display: block; }
.wev-auto .wev-day { margin-bottom: 14px; }
.wev-auto .wev-dayhead { padding: 6px 4px; border: 0; border-bottom: 1px solid #3a3430; border-radius: 0; background: none; }
.wev-auto .wev-day-today .wev-dayhead { border-bottom-color: rgba(232, 225, 214, .55); background: none; }
.wev-auto .wev-events { margin-top: 8px; gap: 8px; }
.wev-auto .wev-ev { grid-template-columns: 40px minmax(0, 1fr) auto; grid-template-areas: "ico text time"; align-items: center; gap: 12px; padding: 8px 12px 8px 8px; }
.wev-auto .wev-ev .wev-ico { width: 40px; height: 40px; }
.wev-auto .wev-ev .wev-text { margin: 0; flex-direction: column; flex-wrap: nowrap; align-items: stretch; gap: 1px; }
.wev-auto .wev-ev .wev-sub { font-size: 12px; }
