.wev-js.wev-auto .wev-day:not(.wev-open) .wev-events { display: none; }
}
@media (max-width: 500px) {
	.wev-top { flex-direction: column; align-items: stretch; }
	.wev-tz { margin-left: 0; }
	.wev-gcards { grid-template-columns: minmax(0, 1fr); }
}

